create table if not exists cashflow.msp_task(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references cashflow.tenant(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,subscription_id uuid references cashflow.saas_subscription(id) on delete cascade,title text not null check(char_length(trim(title)) between 1 and 180),priority text not null check(priority in('LOW','MEDIUM','HIGH','URGENT')),status text not null default 'OPEN' check(status in('OPEN','IN_PROGRESS','BLOCKED','DONE')),assignee text check(assignee is null or char_length(assignee)<=120),due_date date,source text not null default 'MANUAL' check(source in('MANUAL','RENEWAL','RISK')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists cashflow.msp_task_activity(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references cashflow.tenant(id) on delete cascade,owner_id uuid not null references auth.users(id) on delete cascade,task_id uuid not null references cashflow.msp_task(id) on delete cascade,activity_type text not null check(activity_type in('CREATED','STATUS_CHANGED','COMMENT')),body text not null check(char_length(trim(body)) between 1 and 1000),created_at timestamptz not null default now());
alter table cashflow.msp_task enable row level security;alter table cashflow.msp_task_activity enable row level security;
create policy msp_task_own on cashflow.msp_task for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy msp_task_activity_own on cashflow.msp_task_activity for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
grant select on cashflow.msp_task,cashflow.msp_task_activity to authenticated;
create or replace function cashflow.create_msp_task(p_tenant_id uuid,p_title text,p_priority text,p_assignee text,p_due_date date,p_subscription_id uuid default null,p_source text default 'MANUAL') returns uuid language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_uid uuid:=auth.uid();v_id uuid;begin if not exists(select 1 from cashflow.tenant where id=p_tenant_id and owner_id=v_uid) then raise exception 'tenant_not_found';end if;if p_priority not in('LOW','MEDIUM','HIGH','URGENT') or p_source not in('MANUAL','RENEWAL','RISK') then raise exception 'invalid_task';end if;if p_subscription_id is not null and not exists(select 1 from cashflow.saas_subscription where id=p_subscription_id and tenant_id=p_tenant_id and owner_id=v_uid)then raise exception 'subscription_not_found';end if;insert into cashflow.msp_task(tenant_id,owner_id,subscription_id,title,priority,assignee,due_date,source)values(p_tenant_id,v_uid,p_subscription_id,trim(p_title),p_priority,nullif(trim(p_assignee),''),p_due_date,p_source)returning id into v_id;insert into cashflow.msp_task_activity(tenant_id,owner_id,task_id,activity_type,body)values(p_tenant_id,v_uid,v_id,'CREATED','Tarea creada');return v_id;end$$;
create or replace function cashflow.update_msp_task_status(p_task_id uuid,p_status text,p_comment text default null)returns void language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_uid uuid:=auth.uid();v_task cashflow.msp_task;begin if p_status not in('OPEN','IN_PROGRESS','BLOCKED','DONE')then raise exception 'invalid_status';end if;select * into v_task from cashflow.msp_task where id=p_task_id and owner_id=v_uid for update;if v_task.id is null then raise exception 'task_not_found';end if;update cashflow.msp_task set status=p_status,updated_at=now(),completed_at=case when p_status='DONE'then now()else null end where id=p_task_id;insert into cashflow.msp_task_activity(tenant_id,owner_id,task_id,activity_type,body)values(v_task.tenant_id,v_uid,p_task_id,'STATUS_CHANGED',coalesce(nullif(trim(p_comment),''),'Estado: '||p_status));end$$;
create or replace function cashflow.comment_msp_task(p_task_id uuid,p_body text)returns void language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_uid uuid:=auth.uid();v_task cashflow.msp_task;begin select * into v_task from cashflow.msp_task where id=p_task_id and owner_id=v_uid;if v_task.id is null then raise exception 'task_not_found';end if;insert into cashflow.msp_task_activity(tenant_id,owner_id,task_id,activity_type,body)values(v_task.tenant_id,v_uid,p_task_id,'COMMENT',trim(p_body));end$$;
create or replace function cashflow.msp_task_workspace(p_tenant_id uuid)returns jsonb language sql stable security invoker set search_path=cashflow,public as $$select jsonb_build_object('open_count',count(*)filter(where t.status<>'DONE'),'overdue_count',count(*)filter(where t.status<>'DONE'and t.due_date<current_date),'urgent_count',count(*)filter(where t.status<>'DONE'and t.priority='URGENT'),'tasks',coalesce(jsonb_agg(jsonb_build_object('id',t.id,'title',t.title,'priority',t.priority,'status',t.status,'assignee',t.assignee,'due_date',t.due_date,'source',t.source,'customer',c.name,'activities',(select coalesce(jsonb_agg(jsonb_build_object('type',a.activity_type,'body',a.body,'created_at',a.created_at)order by a.created_at desc),'[]'::jsonb)from cashflow.msp_task_activity a where a.task_id=t.id and a.owner_id=auth.uid()))order by case t.priority when'URGENT'then 1 when'HIGH'then 2 when'MEDIUM'then 3 else 4 end,t.due_date),'[]'::jsonb))from cashflow.msp_task t left join cashflow.saas_subscription s on s.id=t.subscription_id left join cashflow.saas_customer c on c.id=s.customer_id where t.tenant_id=p_tenant_id and t.owner_id=auth.uid()$$;
revoke all on function cashflow.create_msp_task(uuid,text,text,text,date,uuid,text),cashflow.update_msp_task_status(uuid,text,text),cashflow.comment_msp_task(uuid,text),cashflow.msp_task_workspace(uuid) from public;
grant execute on function cashflow.create_msp_task(uuid,text,text,text,date,uuid,text),cashflow.update_msp_task_status(uuid,text,text),cashflow.comment_msp_task(uuid,text),cashflow.msp_task_workspace(uuid) to authenticated;
